function setActiveNav(id) {
  document.querySelectorAll(".nav-link.active").forEach(function (link) {
    link.classList.remove("active");
  });

  var navLink = document.getElementById("nav-" + id);
  if (navLink) {
    navLink.classList.add("active");
  }
}

function setupNavigation() {
  document.querySelectorAll(".nav-link").forEach(function (link) {
    link.addEventListener("click", function () {
      var target = link.getAttribute("href");
      if (target && target.charAt(0) === "#") {
        setActiveNav(target.slice(1));
      }
    });
  });

  if (!("IntersectionObserver" in window)) {
    return;
  }

  var sections = document.querySelectorAll(".page-section[id]");
  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        setActiveNav(entry.target.id);
      }
    });
  }, {
    rootMargin: "-35% 0px -55% 0px",
    threshold: 0.01
  });

  sections.forEach(function (section) {
    observer.observe(section);
  });
}

function deobfuscate() {
  var company = document.getElementById("company");
  var email = document.getElementById("email");
  var tel = document.getElementById("tel");

  if (company) {
    company.innerHTML = company.innerHTML.replace("456 789", "421 392");
  }
  if (email) {
    email.innerHTML = email.innerHTML.replace(" _at_ ", "@");
  }
  if (tel) {
    tel.innerHTML = tel.innerHTML.replace("1234 5678", "7744 0984");
  }
}

function fillText(sectionId, content) {
  var section = document.getElementById(sectionId);
  if (!section || !content) {
    return;
  }

  var title = section.querySelector("[data-content-title]");
  var description = section.querySelector("[data-content-description]");

  if (title && content.title) {
    title.innerHTML = content.title;
  }
  if (description && Array.isArray(content.description)) {
    description.innerHTML = content.description.join("<br>");
  }
}

function getContent() {
  return fetch("/tandem-technology/content.json")
    .then(function (response) {
      if (!response.ok) {
        throw new Error("Unable to load Tandem content");
      }
      return response.json();
    })
    .then(function (content) {
      Object.keys(content).forEach(function (sectionId) {
        fillText(sectionId, content[sectionId]);
      });
    })
    .catch(function (error) {
      console.error(error);
    });
}

document.addEventListener("DOMContentLoaded", function () {
  setupNavigation();
  getContent();
  deobfuscate();
});
